def match(orders):
    import heapq

    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}       # id -> dict(side, price, qty, seq, active)
    trades = []
    seq_counter = 0

    def add_order(oid, side, price, qty, seq):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book:
                info = book[oid]
                if info['active'] and info['qty'] > 0:
                    info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        seq = seq_counter
        seq_counter += 1
        remaining = qty

        if side == 'buy':
            heap = sell_heap
            while remaining > 0 and heap:
                p, s, ooid = heap[0]
                info = book.get(ooid)
                if info is None or not info['active'] or info['qty'] <= 0:
                    heapq.heappop(heap)
                    continue
                if typ != 'market' and price is not None and p > price:
                    break
                heapq.heappop(heap)
                trade_qty = min(remaining, info['qty'])
                trades.append([oid, ooid, p, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] > 0:
                    heapq.heappush(heap, (p, s, ooid))
                else:
                    info['active'] = False

            if typ == 'limit' and remaining > 0:
                add_order(oid, 'buy', price, remaining, seq)

        else:  # sell
            heap = buy_heap
            while remaining > 0 and heap:
                negp, s, ooid = heap[0]
                p = -negp
                info = book.get(ooid)
                if info is None or not info['active'] or info['qty'] <= 0:
                    heapq.heappop(heap)
                    continue
                if typ != 'market' and price is not None and p < price:
                    break
                heapq.heappop(heap)
                trade_qty = min(remaining, info['qty'])
                trades.append([ooid, oid, p, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] > 0:
                    heapq.heappush(heap, (negp, s, ooid))
                else:
                    info['active'] = False

            if typ == 'limit' and remaining > 0:
                add_order(oid, 'sell', price, remaining, seq)

    return trades

